pub fn solve() {
    let now = Instant::now();
    crate::prepare!();
    sc!(n, m, k);
    sc!(ps: [P; n], (g, w): @UndirectedGraphScanner::<Usize1, u64>::new(n, m), qs: [P; k]);
    let mut rng = Xorshift::default();
    let mut qidx: Vec<_> = (0..k).collect();
    let mut bests = (std::i64::MAX, vec![0; n], vec![1; m]);
    let norms: Vec<_> = qs
        .iter()
        .map(|&q| {
            let mut norms: Vec<_> = ps
                .iter()
                .enumerate()
                .filter_map(|(i, &p)| {
                    let norm = (p - q).norm();
                    if norm <= 25_000_000 {
                        Some((norm, i))
                    } else {
                        None
                    }
                })
                .collect();
            norms.sort_unstable();
            norms
        })
        .collect();
    let rnorms: Vec<_> = ps
        .iter()
        .map(|&p| {
            let mut norms: Vec<_> = qs
                .iter()
                .enumerate()
                .filter_map(|(j, &q)| {
                    let norm = (p - q).norm();
                    if norm <= 25_000_000 {
                        Some((norm, j))
                    } else {
                        None
                    }
                })
                .collect();
            norms.sort_unstable();
            norms
        })
        .collect();
    let mut memo = HashMap::<Vec<bool>, Vec<i64>>::new();
    let sp: Vec<_> = (0..n)
        .map(|s| {
            let mut dist = vec![!0u64; n];
            let mut par: Vec<Option<(usize, Adjacency)>> = vec![None; n];
            dist[s] = 0;
            let mut heap = BinaryHeap::new();
            heap.push((Reverse(0u64), s));
            while let Some((Reverse(d), u)) = heap.pop() {
                if dist[u] != d {
                    continue;
                }
                for a in g.adjacencies(u) {
                    let nd = d + w[a.id];
                    if nd < dist[a.to] {
                        dist[a.to] = nd;
                        par[a.to] = Some((u, *a));
                        heap.push((Reverse(nd), a.to));
                    }
                }
            }
            (dist, par)
        })
        .collect();

    let mut _cnt = 0usize;
    let mut _cnt2 = 0usize;
    while now.elapsed().as_secs_f64() < 1.95 {
        _cnt += 1;
        rng.shuffle(&mut qidx);
        let mut power = bests.1.to_vec();
        let mut update = vec![_cnt == 1; k];
        if _cnt > 1 {
            for i in 0..n {
                let p2 = power[i] * power[i];
                if rng.gen_bool(0.1) {
                    for &(norm, j) in &rnorms[i] {
                        if norm > p2 {
                            break;
                        }
                        update[j] |= true;
                    }
                    power[i] = 0;
                }
            }
        }
        for &j in &qidx {
            if !update[j] {
                continue;
            }
            let (norm, i) = norms[j]
                .iter()
                .min_by_key(|&&(norm, i)| norm - power[i] * power[i])
                .cloned()
                .unwrap();
            let pow = (norm as f64).sqrt().ceil() as i32;
            if power[i] < pow {
                power[i] = pow;
            }
        }

        let cond: Vec<_> = power.iter().map(|&pow| pow > 0).collect();
        let onoff = if let Some(onoff) = memo.get(&cond) {
            onoff.to_vec()
        } else {
            _cnt2 += 1;
            let mut used = vec![false; n];
            let mut onoff = vec![0; m];
            let mut heap = BinaryHeap::new();
            mlambda!(
                fn push(s: usize) {
                    used[s] = true;
                    for u in g.vertices() {
                        if !used[u] && power[u] > 0 {
                            heap.push((Reverse(sp[s].0[u]), s, u));
                        }
                    }
                }
            );
            push!(0);
            while let Some((_, p, u)) = heap.pop() {
                if used[u] || power[u] == 0 {
                    continue;
                }
                let mut x = u;
                while let Some((p, a)) = sp[p].1[x] {
                    onoff[a.id] = 1;
                    x = p;
                }
                push!(u);
            }

            memo.insert(cond, onoff.to_vec());
            onoff
        };
        let wsum: i64 = onoff
            .iter()
            .enumerate()
            .map(|(i, &on)| w[i] as i64 * on)
            .sum();
        let score = wsum as i64 + power.iter().map(|&p| p as i64 * p as i64).sum::<i64>();
        if score < bests.0 {
            bests = (score, power, onoff);
        }
    }

    let (_, power, onoff) = bests;
    pp!(@it &power; @it &onoff);
    let wsum: i64 = onoff
        .iter()
        .enumerate()
        .map(|(i, &on)| w[i] as i64 * on)
        .sum();
    eprintln!("wsum = {:?}", wsum);
    let score = wsum as i64 + power.iter().map(|&p| p as i64 * p as i64).sum::<i64>();
    eprintln!("S = {:?}", score);
    let score = (1e6 * (1f64 + 1e8 / (score as f64 + 1e7))).round() as i64;
    eprintln!("score = {:?}", score);

    eprintln!("cnt = {:?}", _cnt);
    eprintln!("cnt2 = {:?}", _cnt2);
}
type P = Complex<i32>;
crate::main!();
